<template><Modal :value="visible" :title="record?'编辑收付通配置':'新增独立收付通配置'" width="850" :mask-closable="false" :closable="!disabled" footer-hide @on-visible-change="v=>{if(!v&&visible)$emit('cancel')}"><div class="s1-ui"><Alert v-if="record" type="warning" show-icon>保存会停用本配置并使旧核验失效。账号只读摘要为掩码，编辑时必须重新填写完整获准账号，不能把掩码保存为真实值。</Alert><Form :model="form" :label-width="160"><DetailSection title="配置与运行模式" :grid="false"><FormItem label="配置名称" required><Input v-model="form.name" maxlength="60" :disabled="disabled"/></FormItem><FormItem label="渠道模式" required><Select v-model="form.mode" :disabled="disabled||!!record"><Option value="MOCK">模拟渠道</Option><Option value="REAL">真实渠道</Option></Select><p class="ui-note">运行环境由服务端确定；本候选未授权真实渠道出站。</p></FormItem></DetailSection><DetailSection title="平台账户与支付应用" :grid="false"><FormItem label="平台服务商商户号" required><Input v-model="form.providerMchid" maxlength="64" :disabled="disabled"/><p class="ui-note">{{form.mode==='MOCK'?'仅合成值，以MOCK_开头。':'仅填写已获准的平台账户，不据格式判断渠道就绪。'}}</p></FormItem><FormItem label="实际支付AppID" required><Input v-model="form.paymentAppId" maxlength="128" :disabled="disabled"/></FormItem><FormItem v-if="form.mode==='MOCK'" label="模拟比例上限"><PercentInput :key="key" v-model="form.mockMaxRateBps" :disabled="disabled"/><p class="ui-note">未填写为未知，0%为明确零上限。</p></FormItem><FormItem v-else label="受控凭据引用"><Input v-model="form.credentialRef" maxlength="64" :disabled="disabled"/><p class="ui-note">只填部署方的引用名；不粘贴密钥、私钥或证书。编辑时留空保留原引用。</p></FormItem></DetailSection><FormItem label="变更原因" required><Input v-model="form.reason" type="textarea" :rows="3" maxlength="500" :disabled="disabled"/></FormItem></Form><p v-if="localError||error" class="ui-error">{{localError||error}}</p><footer class="ui-form-footer"><Button :disabled="busy" @click="$emit('cancel')">取消</Button><Button type="primary" :loading="busy" :disabled="disabled" @click="save">保存未启用配置</Button></footer></div></Modal></template>
<script>import accessible from '../accessibility';import DetailSection from './DetailSection';import PercentInput from './PercentInput';export default {mixins:[accessible],components:{DetailSection,PercentInput},props:{visible:Boolean,record:Object,disabled:Boolean,busy:Boolean,error:String},data:()=>({form:{},localError:'',key:0}),watch:{visible(value){if(value){this.key++;this.localError='';const r=this.record;this.form={name:r?r.name:'',mode:r?r.mode:'MOCK',providerMchid:'',paymentAppId:'',mockMaxRateBps:r?r.mockMaxRateBps:null,credentialRef:'',reason:''};}},form:{deep:true,handler(){if(this.visible)this.$emit('dirty');}}},methods:{save(){this.localError='';for(const [key,label] of [['name','配置名称'],['providerMchid','平台服务商商户号'],['paymentAppId','实际支付AppID'],['reason','变更原因']])if(!String(this.form[key]||'').trim()){this.localError='请填写'+label+'。';return;}const body={...this.form};if(this.record){delete body.mode;body.expectedVersion=this.record.version;}if(!body.credentialRef)delete body.credentialRef;if(this.form.mode==='REAL')delete body.mockMaxRateBps;else delete body.credentialRef;this.$emit('save',body);}}};</script>
